 "content": "from collections import Counter


def transform(grid):
    """Repeat the occupied tile across equal regions separated by a solid line."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # A solid non-background row/column marks boundaries between repeated tiles.
    row_cuts = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    col_cuts = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def regions(size, cuts):
        out, start = [], 0
        for cut in cuts:
            out.append((start, cut))
            start = cut + 1
        out.append((start, size))
        return out

    # In these tasks the separator orientation identifies the repetition axis.
    if row_cuts:
        rs = regions(h, row_cuts)
        widths = [b - a for a, b in rs]
        candidates = [(a, b) for (a, b), n in zip(rs, widths) if n == max(widths)]
        # Prefer an occupied region among the largest equal-sized bands.
        def score(ab):
            a, b = ab
            return sum(v != bg for row in grid[a:b] for v in row)
        template = max(candidates, key=score)
        ta, tb = template
        out = [row[:] for row in grid]
        for a, b in rs:
            if b - a == tb - ta:
                for k in range(b - a):
                    out[a + k] = grid[ta + k][:]
        return out

    if col_cuts:
        cs = regions(w, col_cuts)
        widths = [b - a for a, b in cs]
        candidates = [(a, b) for (a, b), n in zip(cs, widths) if n == max(widths)]
        def score(ab):
            a, b = ab
            return sum(grid[r][c] != bg for r in range(h) for c in range(a, b))
        ta, tb = max(candidates, key=score)
        out = [row[:] for row in grid]
        for a, b in cs:
            if b - a == tb - ta:
                for r in range(h):
                    out[r][a:b] = grid[r][ta:tb]
        return out
    return [row[:] for row in grid]
